function ad_scalar(string $sql,array $params=[]): float {try{$q=db()->prepare($sql);$q->execute($params);return (float)($q->fetchColumn()?:0);}catch(Throwable $e){return 0;}}
function ad_rows(string $sql,array $params=[]): array {try{$q=db()->prepare($sql);$q->execute($params);return $q->fetchAll();}catch(Throwable $e){return [];}}
function ad_normalize_status(string $status,?string $start,?string $end): string {
    if(!in_array($status,ad_statuses(),true))$status='pending';$now=time();$s=$start?strtotime($start):null;$e=$end?strtotime($end):null;
    if($e&&$e<$now)return 'completed';if($status==='active'&&$s&&$s>$now)return 'scheduled';return $status;
}

if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  csrf_check();$action=(string)($_POST['action']??'save');$id=(int)($_POST['id']??0);
  if($action==='delete'){
    db()->prepare("DELETE FROM advertisements WHERE id=?")->execute([$id]);$msg='Advertisement deleted.';
  }elseif(in_array($action,['activate','pause','complete','reject'],true)){
    $status=['activate'=>'active','pause'=>'paused','complete'=>'completed','reject'=>'rejected'][$action];
    if($status==='active')db()->prepare("UPDATE advertisement_details SET approved_by=?,approved_at=NOW() WHERE advertisement_id=?")->execute([$uid?:null,$id]);
    db()->prepare("UPDATE advertisements SET status=? WHERE id=?")->execute([$status,$id]);ad_sync_scheduled_statuses();$msg='Campaign status changed to '.$status.'.';
  }elseif($action==='duplicate'){
    $q=db()->prepare("SELECT * FROM advertisements WHERE id=?");$q->execute([$id]);$a=$q->fetch();if(!$a)throw new RuntimeException('Campaign not found.');
    $q=db()->prepare("INSERT INTO advertisements(business_id,title,placement,image_url,target_url,start_at,end_at,status,budget) VALUES(?,?,?,?,?,?,?,'pending',?)");$q->execute([$a['business_id'],$a['title'].' Copy',$a['placement'],$a['image_url'],$a['target_url'],null,null,$a['budget']]);$newId=(int)db()->lastInsertId();
    db()->prepare("INSERT INTO advertisement_details(advertisement_id,pricing_model,rate,impressions,clicks,target_city_id,target_category_id,charge_amount,notes,description,alt_text,device_target,priority,impression_limit,click_limit,frequency_cap,audience_note,billing_status) SELECT ?,pricing_model,rate,0,0,target_city_id,target_category_id,charge_amount,notes,description,alt_text,device_target,priority,impression_limit,click_limit,frequency_cap,audience_note,'unpaid' FROM advertisement_details WHERE advertisement_id=?")->execute([$newId,$id]);$msg='Campaign duplicated as pending.';
  }else{
    $business=(int)($_POST['business_id']??0)?:null;$title=trim((string)($_POST['title']??''));if($title==='')throw new RuntimeException('Campaign title is required.');
    $placement=(string)($_POST['placement']??'homepage_top');if(!isset(ad_placements()[$placement]))throw new RuntimeException('Invalid advertisement placement.');
    $pricing=(string)($_POST['pricing_model']??'flat');if(!isset(ad_pricing_models()[$pricing]))throw new RuntimeException('Invalid pricing model.');
    $device=(string)($_POST['device_target']??'all');if(!isset(ad_device_targets()[$device]))throw new RuntimeException('Invalid device target.');
    $billing=(string)($_POST['billing_status']??'unpaid');if(!isset(ad_billing_statuses()[$billing]))throw new RuntimeException('Invalid billing status.');
    $targetUrl=trim((string)($_POST['target_url']??''));if(!ad_valid_target_url($targetUrl))throw new RuntimeException('Target URL must be a valid http(s) URL or a root-relative URL such as /search.php.');
    $start=trim((string)($_POST['start_at']??''))?:null;$end=trim((string)($_POST['end_at']??''))?:null;if($start&&$end&&strtotime($end)<=strtotime($start))throw new RuntimeException('End date/time must be after start date/time.');
    $budget=max(0,(float)($_POST['budget']??0));$rate=max(0,(float)($_POST['rate']??0));$charge=max(0,(float)($_POST['charge_amount']??0));if(in_array($pricing,['cpc','cpm'],true)&&$rate<=0)throw new RuntimeException('CPC/CPM campaigns require a rate greater than zero.');
    if($pricing==='flat'&&$charge<=0&&$budget<=0)throw new RuntimeException('Flat campaigns require a charge amount or budget.');
    $status=ad_normalize_status((string)($_POST['status']??'pending'),$start,$end);if($status==='scheduled'&&!$start)throw new RuntimeException('Scheduled campaigns require a start date/time.');
    $image=trim((string)($_POST['image_url']??''));if(isset($_FILES['ad_image'])){$up=upload_homepage_image($_FILES['ad_image']);if($up)$image=$up;}
    $city=(int)($_POST['target_city_id']??0)?:null;$category=(int)($_POST['target_category_id']??0)?:null;$priority=max(1,min(100,(int)($_POST['priority']??10)));$impLimit=max(0,(int)($_POST['impression_limit']??0));$clickLimit=max(0,(int)($_POST['click_limit']??0));$freq=max(0,min(100,(int)($_POST['frequency_cap']??0)));
    if($id){
      db()->prepare("UPDATE advertisements SET business_id=?,title=?,placement=?,image_url=?,target_url=?,start_at=?,end_at=?,status=?,budget=? WHERE id=?")->execute([$business,$title,$placement,$image,$targetUrl,$start,$end,$status,$budget,$id]);
    }else{
      db()->prepare("INSERT INTO advertisements(business_id,title,placement,image_url,target_url,start_at,end_at,status,budget) VALUES(?,?,?,?,?,?,?,?,?)")->execute([$business,$title,$placement,$image,$targetUrl,$start,$end,$status,$budget]);$id=(int)db()->lastInsertId();
    }
    $approvedBy=$status==='active'?($uid?:null):null;$approvedAt=$status==='active'?date('Y-m-d H:i:s'):null;
    db()->prepare("INSERT INTO advertisement_details(advertisement_id,pricing_model,rate,target_city_id,target_category_id,charge_amount,notes,description,alt_text,device_target,priority,impression_limit,click_limit,frequency_cap,audience_note,billing_status,approved_by,approved_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE pricing_model=VALUES(pricing_model),rate=VALUES(rate),target_city_id=VALUES(target_city_id),target_category_id=VALUES(target_category_id),charge_amount=VALUES(charge_amount),notes=VALUES(notes),description=VALUES(description),alt_text=VALUES(alt_text),device_target=VALUES(device_target),priority=VALUES(priority),impression_limit=VALUES(impression_limit),click_limit=VALUES(click_limit),frequency_cap=VALUES(frequency_cap),audience_note=VALUES(audience_note),billing_status=VALUES(billing_status),approved_by=IF(VALUES(approved_by) IS NULL,approved_by,VALUES(approved_by)),approved_at=IF(VALUES(approved_at) IS NULL,approved_at,VALUES(approved_at))")->execute([$id,$pricing,$rate,$city,$category,$charge,trim((string)($_POST['notes']??'')),trim((string)($_POST['description']??'')),trim((string)($_POST['alt_text']??'')),$device,$priority,$impLimit,$clickLimit,$freq,trim((string)($_POST['audience_note']??'')),$billing,$approvedBy,$approvedAt]);
    ad_sync_scheduled_statuses();$msg='Advertisement campaign saved successfully.';
  }
 }catch(Throwable $e){$err=$e->getMessage();}
}

