$sql="SELECT a.*,b.name business_name,d.pricing_model,d.rate,d.impressions,d.clicks,d.charge_amount,d.target_city_id,d.target_category_id,d.device_target,d.priority,d.impression_limit,d.click_limit,d.frequency_cap,d.billing_status,d.description,d.audience_note,c.name target_city,cat.name target_category,(SELECT COUNT(*) FROM payment_orders po WHERE po.advertisement_id=a.id AND po.status='paid') paid_orders FROM advertisements a LEFT JOIN businesses b ON b.id=a.business_id LEFT JOIN advertisement_details d ON d.advertisement_id=a.id LEFT JOIN cities c ON c.id=d.target_city_id LEFT JOIN categories cat ON cat.id=d.target_category_id";if($where)$sql.=' WHERE '.implode(' AND ',$where);$sql.=' ORDER BY FIELD(a.status,\'active\',\'scheduled\',\'pending\',\'paused\',\'completed\',\'rejected\'),COALESCE(d.priority,10) DESC,a.id DESC LIMIT 400';$q=db()->prepare($sql);$q->execute($params);$rows=$q->fetchAll();
$all=ad_rows("SELECT a.*,d.pricing_model,d.rate,d.impressions,d.clicks,d.charge_amount,d.billing_status FROM advertisements a LEFT JOIN advertisement_details d ON d.advertisement_id=a.id");
$total=count($all);$active=0;$scheduled=0;$pending=0;$views=0;$clicks=0;$budget=0;$spend=0;$paidCount=0;foreach($all as $a){$active+=($a['status']==='active');$scheduled+=($a['status']==='scheduled');$pending+=($a['status']==='pending');$views+=(int)$a['impressions'];$clicks+=(int)$a['clicks'];$budget+=(float)$a['budget'];$spend+=ad_effective_spend($a);$paidCount+=($a['billing_status']==='paid');}$ctr=$views?round(($clicks/$views)*100,2):0;
