<section class="card ad-form-section"><div class="ad-section-head"><i>3</i><div><h3>Schedule & Delivery Limits</h3><span>Control exactly when and how much the campaign can deliver.</span></div></div><div class="ad-form-grid"><div><label>Start Date / Time</label><input class="input" type="datetime-local" name="start_at" value="<?=e(ad_datetime_input($edit['start_at']??null))?>"></div><div><label>End Date / Time</label><input class="input" type="datetime-local" name="end_at" value="<?=e(ad_datetime_input($edit['end_at']??null))?>"></div><div><label>Priority (1–100)</label><input class="input" type="number" min="1" max="100" name="priority" value="<?=e($edit['priority']??setting_int('ad_default_priority',10))?>"><small>Higher priority campaigns are considered first.</small></div><div><label>Frequency Cap</label><input class="input" type="number" min="0" max="100" name="frequency_cap" value="<?=e($edit['frequency_cap']??setting_int('ad_default_frequency_cap',0))?>"><small>Max impressions per visitor/session per day. 0 = unlimited.</small></div><div><label>Impression Limit</label><input class="input" type="number" min="0" name="impression_limit" value="<?=e($edit['impression_limit']??0)?>"><small>0 = unlimited.</small></div><div><label>Click Limit</label><input class="input" type="number" min="0" name="click_limit" value="<?=e($edit['click_limit']??0)?>"><small>Campaign auto-completes at limit.</small></div></div></section>
<section class="card ad-form-section"><div class="ad-section-head"><i>4</i><div><h3>Audience Targeting</h3><span>Choose city, business category and device audience.</span></div></div><div class="ad-form-grid"><div><label>Target City</label><select class="input" name="target_city_id"><option value="">All Cities</option><?php foreach($cities as $c):?><option value="<?=e($c['id'])?>" <?=($edit['target_city_id']??0)==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div><label>Target Category</label><select class="input" name="target_category_id"><option value="">All Categories</option><?php foreach($categories as $c):?><option value="<?=e($c['id'])?>" <?=($edit['target_category_id']??0)==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div><label>Device</label><select class="input" name="device_target"><?php foreach(ad_device_targets() as $v=>$label):?><option value="<?=e($v)?>" <?=($edit['device_target']??'all')===$v?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></div><div class="full"><label>Audience Notes</label><textarea class="input" rows="2" name="audience_note" placeholder="Internal note: e.g. target families, students, restaurant customers..."><?=e($edit['audience_note']??'')?></textarea></div></div></section>
<section class="card ad-form-section"><div class="ad-section-head"><i>5</i><div><h3>Pricing & Billing</h3><span>Define how the campaign earns revenue.</span></div></div><div class="ad-form-grid"><div><label>Pricing Model</label><select class="input" name="pricing_model" id="adPricing"><?php foreach(ad_pricing_models() as $v=>$label):?><option value="<?=e($v)?>" <?=($edit['pricing_model']??'flat')===$v?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></div><div><label>Rate (PKR)</label><input class="input" type="number" min="0" step="0.01" name="rate" value="<?=e($edit['rate']??0)?>"><small id="rateHint">Flat: optional if Charge Amount is set.</small></div><div><label>Total Budget (PKR)</label><input class="input" type="number" min="0" step="0.01" name="budget" value="<?=e($edit['budget']??0)?>"></div><div><label>Charge Amount (PKR)</label><input class="input" type="number" min="0" step="0.01" name="charge_amount" value="<?=e($edit['charge_amount']??0)?>"></div><div><label>Billing Status</label><select class="input" name="billing_status"><?php foreach(ad_billing_statuses() as $v=>$label):?><option value="<?=e($v)?>" <?=($edit['billing_status']??'unpaid')===$v?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></div><div class="full"><label>Internal Notes</label><textarea class="input" rows="3" name="notes"><?=e($edit['notes']??'')?></textarea></div></div></section>
<div class="ad-form-actions"><a class="btn ghost" href="?tab=campaigns">Cancel</a><button class="btn" type="submit"><?=e($edit?'Update Campaign':'Create Campaign')?></button></div>
</main><aside class="ad-form-sidebar"><section class="card ad-preview-card"><div class="ad-panel-head"><div><h3>Creative Preview</h3><span>Approximate sponsored placement preview.</span></div></div><div class="ad-preview-image" id="adPreviewImage" <?=$edit&&$edit['image_url']?'style="background-image:url(\''.e($edit['image_url']).'\')"':''?>><span>AD</span></div><div class="ad-preview-copy"><small>SPONSORED</small><h4 id="adPreviewTitle"><?=e($edit['title']??'Campaign Title')?></h4><p id="adPreviewDescription"><?=e($edit['description']??'Your campaign description will appear here.')?></p><button type="button">View Offer</button></div></section><section class="card form-guide"><h3>Campaign Checklist</h3><ul><li>Use recommended creative size</li><li>Use a valid destination URL</li><li>Set start/end dates correctly</li><li>Choose accurate audience targeting</li><li>Configure pricing and billing</li><li>Activate only after advertiser approval/payment</li></ul><?php if($edit):?><div class="performance-box"><span>Current Performance</span><b><?=e(number_format((int)($edit['impressions']??0)))?> views</b><b><?=e(number_format((int)($edit['clicks']??0)))?> clicks</b><b><?=e(number_format(ad_ctr($edit),2))?>% CTR</b><strong>Rs <?=e(number_format(ad_effective_spend($edit),2))?> spend</strong></div><?php endif;?></section></aside></div></form>
<script>
(function(){const placement=document.getElementById('adPlacement'),hint=document.getElementById('placementHint'),title=document.querySelector('[name="title"]'),desc=document.querySelector('[name="description"]'),previewTitle=document.getElementById('adPreviewTitle'),previewDesc=document.getElementById('adPreviewDescription'),url=document.getElementById('adImageUrl'),file=document.getElementById('adImageFile'),img=document.getElementById('adPreviewImage'),pricing=document.getElementById('adPricing'),rateHint=document.getElementById('rateHint');function p(){const o=placement.options[placement.selectedIndex];hint.innerHTML='<b>'+o.dataset.size+'</b><span>'+o.dataset.hint+'</span>'}function pricingHint(){rateHint.textContent=pricing.value==='cpc'?'Rate charged per click.':pricing.value==='cpm'?'Rate charged per 1,000 impressions.':'Flat: rate optional; use Charge Amount or Budget.'}placement?.addEventListener('change',p);pricing?.addEventListener('change',pricingHint);title?.addEventListener('input',()=>previewTitle.textContent=title.value||'Campaign Title');desc?.addEventListener('input',()=>previewDesc.textContent=desc.value||'Your campaign description will appear here.');url?.addEventListener('input',()=>{if(url.value)img.style.backgroundImage='url("'+url.value.replace(/"/g,'')+'")'});file?.addEventListener('change',()=>{const f=file.files?.[0];if(f){const r=new FileReader();r.onload=e=>img.style.backgroundImage='url("'+e.target.result+'")';r.readAsDataURL(f)}});p();pricingHint()})();
</script>
<?php endif;?>
<?php require __DIR__.'/../app/end.php';?>
